C The STR$ routines from FORTRAN (Phase 83, subtask 9): a CHARACTER variable
C is a fixed string, so each routine's status says whether it fit, and a
C position or a count is passed by reference, as a constant is.
      PROGRAM STRRTL
      IMPLICIT NONE
      INCLUDE '($SSDEF)'
      INCLUDE '($STRDEF)'
      CHARACTER*8 A
      CHARACTER*3 B
      CHARACTER*60 C
      INTEGER*2 L
      INTEGER STATUS, I, J, TRYAPP
      INTEGER STR$COPY_DX, STR$UPCASE, STR$CONCAT, STR$TRIM, STR$LEFT
      INTEGER STR$RIGHT, STR$POS_EXTR, STR$LEN_EXTR, STR$REPLACE
      INTEGER STR$DUPL_CHAR, STR$ELEMENT, STR$TRANSLATE, STR$COMPARE
      INTEGER STR$COMPARE_EQL, STR$CASE_BLIND_COMPARE, STR$COMPARE_MULTI
      INTEGER STR$POSITION, STR$FIND_FIRST_IN_SET
      INTEGER STR$FIND_FIRST_NOT_IN_SET, STR$FIND_FIRST_SUBSTRING
      INTEGER STR$MATCH_WILD, SYS$GETMSG

      STATUS = STR$COPY_DX(A, 'HELLO')
      PRINT 100, 'COPY_DX', A, STATUS .EQ. SS$_NORMAL
      STATUS = STR$COPY_DX(B, 'HELLO')
      PRINT 100, 'TRUNCATED', B, STATUS .EQ. STR$_TRU
      STATUS = STR$UPCASE(A, 'abc1d')
      PRINT 100, 'UPCASE', A, STATUS .EQ. SS$_NORMAL
      STATUS = STR$CONCAT(A, 'AB', 'CD', 'E')
      PRINT 100, 'CONCAT', A, STATUS .EQ. SS$_NORMAL
      STATUS = STR$TRIM(C, 'XY   ', L)
      PRINT 100, 'TRIM', C(1:L), L .EQ. 2

      STATUS = STR$LEFT(A, 'ABCDE', 2)
      PRINT 100, 'LEFT', A, STATUS .EQ. SS$_NORMAL
      STATUS = STR$RIGHT(A, 'ABCDE', 4)
      PRINT 100, 'RIGHT', A, STATUS .EQ. SS$_NORMAL
      STATUS = STR$POS_EXTR(A, 'ABCDE', 2, 4)
      PRINT 100, 'POS_EXTR', A, STATUS .EQ. SS$_NORMAL
      STATUS = STR$LEN_EXTR(A, 'ABCDE', 0, 2)
      PRINT 100, 'LEN_EXTR', A, STATUS .EQ. STR$_ILLSTRPOS
      STATUS = STR$REPLACE(A, 'ABCDE', 2, 3, 'xyz')
      PRINT 100, 'REPLACE', A, STATUS .EQ. SS$_NORMAL

      STATUS = STR$DUPL_CHAR(A, 3, %REF('Z'))
      PRINT 100, 'DUPL_CHAR', A, STATUS .EQ. SS$_NORMAL
      STATUS = STR$DUPL_CHAR(A, 2, )
      PRINT 100, 'DUPL blanks', A, STATUS .EQ. SS$_NORMAL
      STATUS = STR$ELEMENT(A, 1, ',', 'AB,CD,EF')
      PRINT 100, 'ELEMENT', A, STATUS .EQ. SS$_NORMAL
      STATUS = STR$ELEMENT(A, 5, ',', 'AB,CD,EF')
      PRINT 100, 'NO ELEMENT', A, STATUS .EQ. STR$_NOELEM
      STATUS = STR$TRANSLATE(A, 'ABCDA', 'xy', 'AB')
      PRINT 100, 'TRANSLATE', A, STATUS .EQ. SS$_NORMAL

      PRINT 101, 'COMPARE', STR$COMPARE('AB', 'AB  ')
      PRINT 101, 'COMPARE', STR$COMPARE('AB', 'AC')
      PRINT 101, 'EQL', STR$COMPARE_EQL('AB', 'AB  ')
      PRINT 101, 'BLIND', STR$CASE_BLIND_COMPARE('abc', 'ABC')
      PRINT 101, 'MULTI', STR$COMPARE_MULTI('abc', 'ABC')
      PRINT 101, 'MULTI blind', STR$COMPARE_MULTI('abc', 'ABC', %VAL(1))

      PRINT 101, 'POSITION', STR$POSITION('ABCAB', 'AB', 2)
      PRINT 101, 'IN SET', STR$FIND_FIRST_IN_SET('ABCDE', 'XDC')
      PRINT 101, 'NOT IN SET', STR$FIND_FIRST_NOT_IN_SET('AAB', 'BA')
      STATUS = STR$FIND_FIRST_SUBSTRING('ABCDE', I, J, 'DE', 'BC')
      PRINT 102, 'SUBSTRING', STATUS, I, J
      PRINT 103, 'WILD', STR$MATCH_WILD('abc', 'a%c') .EQ. STR$_MATCH
      PRINT 103, 'WILD', STR$MATCH_WILD('abc', 'b*') .EQ. STR$_NOMATCH

C Appending to a fixed string is a condition, signaled: a handler turns it
C into the status its establisher returns.
      PRINT 103, 'ILLSTRCLA', TRYAPP(A) .EQ. STR$_ILLSTRCLA
      PRINT 100, 'UNCHANGED', A, .TRUE.

      STATUS = SYS$GETMSG(%VAL(STR$_TRU), L, C, %VAL(15), )
      PRINT '(1X,A)', C(1:L)
      STATUS = SYS$GETMSG(%VAL(STR$_ILLSTRPOS), L, C, %VAL(15), )
      PRINT '(1X,A)', C(1:L)

  100 FORMAT (1X, A, T14, '"', A, '" ', L1)
  101 FORMAT (1X, A, T14, I3)
  102 FORMAT (1X, A, T14, 3I3)
  103 FORMAT (1X, A, T14, L1)
      END

      INTEGER FUNCTION TRYAPP(A)
      CHARACTER*(*) A
      EXTERNAL LIB$SIG_TO_RET
      INTEGER STR$APPEND
      CALL LIB$ESTABLISH(LIB$SIG_TO_RET)
      TRYAPP = STR$APPEND(A, 'MORE')
      END
